        // cutoff) and is NOT a literal hit, so this exercises the fuzzy branch.
        item.old_text = "hello world";
        item.new_text = "HI";
        const plan_edit_result r = apply_plan_edit("hellp world\n", item);
        expect(r.replacements == 1u);
        expect(sv_of(r.content) == std::string("HI\n"));
        // This is where EditPlan differs from the file edit tool: a
        // successful fuzzy match reports NO suggestion.
        expect(!r.suggestion.has_value());
