        expect(sv_of(no_plan_path_message("ReadPlan")) == std::string("ReadPlan tool invalid: no plan_writing_path set."));
        expect(sv_of(no_plan_path_message("EditPlan")) == std::string("EditPlan tool invalid: no plan_writing_path set."));
