        expect(sv_of(plan_written_message("overwrite", "p.md")) == std::string("Plan written to p.md"));
        expect(sv_of(plan_written_message("append", "p.md")) == std::string("Plan appended to p.md"));
        expect(sv_of(no_replacements_message("")) == std::string("No replacements were made. The old string was not found "
                   "in the plan file."));
