    "tool_meta_matches_the_reference"_test = [] {
        for (const plan_meta_golden &g : kPlanMeta) {
            const ToolMeta *meta = ToolRegistry::instance().find(g.tool);
            expect(meta != nullptr) << "not registered: " << g.tool;
            if (meta == nullptr) {
                continue;
            }
            expect(sv_of(meta->description) == std::string(g.description))
                << "description mismatch: " << g.tool;
            ToolParams want;
            ToolParams got;
            expect(parse_json(g.params_json, want)) << g.tool;
            expect(parse_json(sv_of(meta->parameters_json), got)) << g.tool;
            expect(json_equal(ValueElement::make_object(
                                  kimix::shared_ptr<ToolParams>(
                                      new ToolParams(std::move(want)))),
                              ValueElement::make_object(
                                  kimix::shared_ptr<ToolParams>(
                                      new ToolParams(std::move(got))))))
                << "parameter schema mismatch: " << g.tool;
        }
    };

    // -----------------------------------------------------------------------
    // Golden replay: parameter validation matrix
    // -----------------------------------------------------------------------
    "param_matrix_matches_the_reference"_test = [] {
        for (const plan_param_golden &g : kPlanParamGoldens) {
            ToolParams params;
            expect(parse_json(g.params_json, params))
                << "golden params are not JSON: " << g.name;
            bool accepted = false;
            const std::string tool(g.tool);
            if (tool == "WritePlan") {
                write_plan_params out;
                accepted = !parse_write_params(&params, out).failed();
            } else if (tool == "ReadPlan") {
                read_plan_params out;
                accepted = !parse_read_params(&params, out).failed();
            } else {
                edit_plan_params out;
                accepted = !parse_edit_params(&params, out).failed();
            }
            if (g.deviation[0] != '\0') {
                expect(g.accepted == 1) << g.name;
                expect(!accepted) << "documented deviation accepted: " << g.name
                                  << " (" << g.deviation << ")";
                continue;
            }
            expect(accepted == (g.accepted == 1))
                << "accept/reject mismatch for " << g.name;
        }
    };

