    // -----------------------------------------------------------------------
    // Golden replay: end-to-end tool calls on real files
    // -----------------------------------------------------------------------
    "tool_replay_goldens"_test = [] {
        std::error_code ec;
        const std::filesystem::path root =
            std::filesystem::temp_directory_path(ec) / "kimix_plan_goldens";
        std::filesystem::remove_all(root, ec);
        std::filesystem::create_directories(root, ec);
        const std::string root_str = root.string();

        for (const plan_tool_golden &g : kPlanToolGoldens) {
            Session session;
            session.plan_enabled = true;
            session.native_io = true;
            std::filesystem::path target;
            if (g.rel_path[0] != '\0') {
            target = native_path(root_str, g.rel_path);
            session.plan_path = kix(target.string());
            if (g.kind == 3) {
                // The target's *parent* must be a regular file.
                expect(write_bytes(target.parent_path(), "i am a file\n"))
                    << g.name;
            } else {
                std::filesystem::create_directories(target.parent_path(), ec);
                if (g.kind == 1) {
                    expect(write_bytes(
                               target,
                               std::string(g.initial,
                                           static_cast<size_t>(g.initial_len))))
                        << g.name;
                } else if (g.kind == 2) {
                    std::filesystem::create_directories(target, ec);
                }
            }
            }
            kimix::unique_ptr<Tool> tool = create_tool(g.tool, &session);
            expect(tool != nullptr) << "no such tool: " << g.tool;
            if (tool == nullptr) {
                continue;
            }
            ToolParams params;
            expect(parse_json(g.params_json, params)) << g.name;
            (*tool)(&params);
            kimix::vector<char> raw;
            tool->result_json(raw);
            const decoded_result got = decode_result(raw);
            expect(got.status == std::string(g.status))
                << "status mismatch for " << g.name << ": " << got.status;
            expect((got.status == "ok") == (g.is_error == 0))
                << "is_error mismatch for " << g.name;
            expect(got.message ==
                   replace_all(g.message, "@PLAN@", root_str))
                << "message mismatch for " << g.name << ": " << got.message;
            expect(got.output ==
                   replace_all(std::string(g.output,
                                           static_cast<size_t>(g.output_len)),
                               "@PLAN@", root_str))
                << "output mismatch for " << g.name;
            expect(got.brief == g.brief) << "brief mismatch for " << g.name;
            if (g.rel_path[0] == '\0') {
                continue;
            }
            // Render bookkeeping (ReadPlan only; -1 == not reported).
            if (std::string(g.tool) == "ReadPlan") {
                if (g.start_line >= 0) {
                    expect(got.start_line == g.start_line) << g.name;
                }
                if (g.total_lines >= 0) {
                    expect(got.total_lines == g.total_lines) << g.name;
                }
                if (g.max_lines_reached >= 0) {
                    expect(got.max_lines_reached == g.max_lines_reached) << g.name;
                }
                if (g.max_bytes_reached >= 0) {
                    expect(got.max_bytes_reached == g.max_bytes_reached) << g.name;
                }
                expect(got.truncated == std::string(g.truncated)) << g.name;
            }
            // On-disk result: the port writes the reference's text verbatim
            // (LF), so `initial`/`write_logical` are byte-exact expectations.
            std::error_code fec;
            const bool exists = std::filesystem::is_regular_file(target, fec);
            if (g.kind == 2) {
                expect(std::filesystem::is_directory(target, fec)) << g.name;
                continue;
            }
            expect(exists == (g.exists_after == 1))
                << "existence mismatch for " << g.name;
            if (!exists) {
                continue;
            }
            std::string bytes;
            expect(read_bytes(target, bytes)) << g.name;
            const std::string initial(g.initial,
                                      static_cast<size_t>(g.initial_len));
            const std::string logical(g.write_logical,
                                      static_cast<size_t>(g.write_logical_len));
            const std::string cpython(g.python_bytes,
                                      static_cast<size_t>(g.python_bytes_len));
            std::string expected(g.initial, static_cast<size_t>(g.initial_len));
            if (g.wrote) {
                if (!g.append) {
                    expected.clear();
                }
                expected += logical;
            }
            expect(bytes == expected)
                << "file content mismatch for " << g.name << ": " << bytes;
            // The documented CPython deviation: the reference writes through a
            // text-mode file object, so every LF of the written text became
            // CRLF on Windows (the bytes it left on disk are recorded in the
            // golden); the port writes the UTF-8 bytes verbatim (asserted
            // above). This pins the translation as the ONLY difference.
            std::string py_expected;
            if (!g.wrote) {
                py_expected = initial;
            } else {
                const std::string base = (g.kind == 1 && g.append) ? initial
                                                                  : std::string();
                py_expected = base + translate_lf(logical);
            }
            expect(cpython == py_expected)
                << "CPython text-mode bytes mismatch for " << g.name;
        }
    };

